import React, { useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useConnectionManager, ConnectionStatus } from './useConnectionManager';

function TextSyncRoom() {
  const { roomId } = useParams<{ roomId: string }>();
  const [text, setText] = useState('');
  
  const {
    connectionStatus,
    errorMessage,
    peers,
    sendData
  } = useConnectionManager({
    roomId: roomId || '',
    onReceiveData: (newText) => setText(newText)
  });

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newText = e.target.value;
    setText(newText);
    sendData(newText);
  };

  const getStatusColor = () => {
    switch (connectionStatus) {
      case ConnectionStatus.CONNECTED:
        return '#22c55e';
      case ConnectionStatus.CONNECTING:
      case ConnectionStatus.RECONNECTING:
        return '#3b82f6';
      case ConnectionStatus.ERROR:
        return '#ef4444';
      default:
        return '#6b7280';
    }
  };

  return (
    <div style={{ padding: '1rem', maxWidth: '40rem', margin: '0 auto' }}>
      <style>
        {`
          @keyframes pulse {
            0% { opacity: 1; }
            50% { opacity: 0.3; }
            100% { opacity: 1; }
          }
        `}
      </style>

      <div style={{ marginBottom: '1rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1rem' }}>
          <Link 
            to="/"
            style={{
              textDecoration: 'none',
              color: '#3b82f6',
              fontSize: '0.875rem'
            }}
          >
            ← Back to Home
          </Link>
          <h1 style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>
            Room: {roomId}
          </h1>
        </div>

        <div 
          style={{
            padding: '10px',
            marginBottom: '15px',
            border: `1px solid ${getStatusColor()}`,
            borderRadius: '4px',
            backgroundColor: `${getStatusColor()}10`,
            color: getStatusColor(),
            display: 'flex',
            alignItems: 'center',
            gap: '8px'
          }}
        >
          <div 
            style={{
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: getStatusColor(),
              animation: (connectionStatus === ConnectionStatus.CONNECTING || 
                         connectionStatus === ConnectionStatus.RECONNECTING) 
                ? 'pulse 1.5s infinite' 
                : 'none'
            }}
          />
          <span>
            {connectionStatus === ConnectionStatus.CONNECTED
              ? `Connected (${peers.length} peer${peers.length === 1 ? '' : 's'})`
              : connectionStatus === ConnectionStatus.CONNECTING
              ? "Connecting..."
              : connectionStatus === ConnectionStatus.RECONNECTING
              ? "Reconnecting..."
              : connectionStatus === ConnectionStatus.ERROR
              ? `Error: ${errorMessage}`
              : "Disconnected"}
          </span>
        </div>
      </div>
      
      <div>
        <label 
          htmlFor="syncedText" 
          style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.875rem' }}
        >
          Shared Text (synced between all peers in this room):
        </label>
        <textarea
          id="syncedText"
          value={text}
          onChange={handleTextChange}
          style={{
            width: '100%',
            height: '10rem',
            padding: '0.5rem',
            border: '1px solid #d1d5db',
            borderRadius: '0.375rem',
            marginBottom: '1rem'
          }}
          placeholder="Type something here..."
          disabled={connectionStatus !== ConnectionStatus.CONNECTED}
        />
      </div>

      <div style={{ fontSize: '0.875rem', color: '#6b7280' }}>
        <p>Debug Info:</p>
        <ul style={{ paddingLeft: '1.25rem', listStyle: 'disc' }}>
          {peers.map(peer => (
            <li key={peer}>Connected peer: {peer}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default TextSyncRoom;