// useConnectionManager.ts
import { useState, useEffect, useCallback, useRef } from 'react';
import { joinRoom, Room } from 'trystero/torrent';

export const ConnectionStatus = {
  DISCONNECTED: 'disconnected',
  CONNECTING: 'connecting',
  CONNECTED: 'connected',
  RECONNECTING: 'reconnecting',
  ERROR: 'error'
} as const;

export type ConnectionStatusType = typeof ConnectionStatus[keyof typeof ConnectionStatus];

const RECONNECT_INTERVAL = 5000;
const MAX_RETRIES = 3;

const config = { 
  appId: 'text-sync-demo',
  relayUrls: [
    'wss://tracker.openwebtorrent.com',
    'wss://tracker.btorrent.xyz',
    'wss://tracker.files.fm:7073/announce',
  ]
};

interface UseConnectionManagerProps {
  roomId: string;
  onReceiveData?: (data: any, peerId: string) => void;
}

interface ConnectionManager {
  connectionStatus: ConnectionStatusType;
  errorMessage: string;
  peers: string[];
  sendData: (data: any, targetPeer?: string) => void;
}

export function useConnectionManager({ roomId, onReceiveData }: UseConnectionManagerProps): ConnectionManager {
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatusType>(ConnectionStatus.DISCONNECTED);
  const [errorMessage, setErrorMessage] = useState('');
  const [peers, setPeers] = useState<string[]>([]);
  
  const roomRef = useRef<Room>();
  const retryCountRef = useRef(0);
  const reconnectIntervalRef = useRef<NodeJS.Timeout>();
  const dataRef = useRef<any>();

  const initializeRoom = useCallback(() => {
    try {
      setConnectionStatus(ConnectionStatus.CONNECTING);
      
      if (roomRef.current) {
        roomRef.current.leave();
      }

      roomRef.current = joinRoom(config, roomId);
      
      const room = roomRef.current;
      const [sendData, getData] = room.makeAction('data');

      // Listen for data updates from other peers
      getData((newData, peerId) => {
        console.log(`Received data from peer ${peerId}:`, newData);
        if (onReceiveData) {
          onReceiveData(newData, peerId);
        }
      });

      // Track peer joins
      room.onPeerJoin(peerId => {
        console.log(`Peer ${peerId} joined`);
        setPeers(prev => {
          if (!prev.includes(peerId)) {
            // Send current data to new peer if we have any
            if (dataRef.current !== undefined) {
              console.log('Sending current data to new peer:', dataRef.current);
              sendData(dataRef.current, peerId).catch(console.error);
            }
            return [...prev, peerId];
          }
          return prev;
        });
      });

      // Track peer leaves
      room.onPeerLeave(peerId => {
        console.log(`Peer ${peerId} left`);
        setPeers(prev => prev.filter(id => id !== peerId));
      });
      
      setConnectionStatus(ConnectionStatus.CONNECTED);
      setErrorMessage('');
      retryCountRef.current = 0;
      
      if (reconnectIntervalRef.current) {
        clearInterval(reconnectIntervalRef.current);
        reconnectIntervalRef.current = undefined;
      }
    } catch (err) {
      handleConnectionError(err);
    }
  }, [roomId, onReceiveData]);

  const handleConnectionError = useCallback((error: any) => {
    console.error('Connection error:', error);
    setConnectionStatus(ConnectionStatus.ERROR);
    setErrorMessage(error.message || 'Failed to connect to the room');

    if (retryCountRef.current < MAX_RETRIES) {
      retryCountRef.current++;
      console.log(`Immediate retry attempt ${retryCountRef.current}`);
      setTimeout(initializeRoom, 1000);
    } else {
      setConnectionStatus(ConnectionStatus.RECONNECTING);
      if (!reconnectIntervalRef.current) {
        reconnectIntervalRef.current = setInterval(initializeRoom, RECONNECT_INTERVAL);
      }
    }
  }, [initializeRoom]);

  // Initialize room on mount or roomId change
  useEffect(() => {
    initializeRoom();

    return () => {
      if (roomRef.current) {
        roomRef.current.leave();
      }
      if (reconnectIntervalRef.current) {
        clearInterval(reconnectIntervalRef.current);
      }
    };
  }, [initializeRoom]);

  const sendData = useCallback((data: any, targetPeer?: string) => {
    if (!roomRef.current) return;

    const [send] = roomRef.current.makeAction('data');
    try {
      dataRef.current = data;
      send(data, targetPeer || null).catch(err => {
        console.error('Error sending data:', err);
        handleConnectionError(err);
      });
    } catch (err) {
      console.error('Error in sendData:', err);
      handleConnectionError(err);
    }
  }, [handleConnectionError]);

  return {
    connectionStatus,
    errorMessage,
    peers,
    sendData
  };
}