// App.tsx
import React, { useEffect } from 'react';
import { useNavigate, useParams, Routes, Route } from 'react-router-dom';
import TextSyncRoom from './TextSyncRoom';

function RoomCreator() {
  const navigate = useNavigate();

  const createRoom = () => {
    // Generate a random room ID (you can make this more sophisticated)
    const roomId = Math.random().toString(36).substring(2, 8);
    navigate(`/room/${roomId}`);
  };

  return (
    <div style={{ padding: '2rem', maxWidth: '40rem', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ fontSize: '2rem', marginBottom: '2rem' }}>Text Sync Rooms</h1>
      <button 
        onClick={createRoom}
        style={{
          padding: '0.75rem 1.5rem',
          fontSize: '1.1rem',
          backgroundColor: '#3b82f6',
          color: 'white',
          border: 'none',
          borderRadius: '0.375rem',
          cursor: 'pointer'
        }}
      >
        Create New Room
      </button>
      <p style={{ marginTop: '2rem', color: '#666' }}>
        Or join a room by entering its ID in the URL: /room/[room-id]
      </p>
    </div>
  );
}

function App() {
  return (
    <Routes>
      <Route path="/" element={<RoomCreator />} />
      <Route path="/room/:roomId" element={<TextSyncRoom />} />
    </Routes>
  );
}

export default App;